/** هسته_مقدار 안의 연결형 بایت_مقدار جریان_مقدار. Ethernet/TCP 패킷 스택이 아닌 루프백 socket لایه_مقدار. */
public final class جریان_شبکه {
    static int[] وضعیت_مقدار = new int[16], تبدیل_مقدار = new int[16], 짝 = new int[16], مشابه_تبدیل = new int[16], منتظر_ماندن_مقدار = new int[16], 묶임 = new int[16];
    static int[] جلو_مقدار = new int[16], 수 = new int[16], داده_ها = new int[16 * 1024];
    static int بعدی_مورد = 50000;
    static int تأیید_صحت(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && وضعیت_مقدار[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int شماره_درگاه) { for (int حلقه_فهرست = 0; حلقه_فهرست < 16; حلقه_فهرست++) if (وضعیت_مقدار[حلقه_فهرست] != 0 && 묶임[حلقه_فهرست] != 0 && تبدیل_مقدار[حلقه_فهرست] == شماره_درگاه) return true; return false; }
    public static int ایجاد_ورودی() {
        for (int حلقه_فهرست = 0; حلقه_فهرست < 16; حلقه_فهرست++) if (وضعیت_مقدار[حلقه_فهرست] == 0) { وضعیت_مقدار[حلقه_فهرست] = 1; مشابه_تبدیل[حلقه_فهرست] = تبدیل_مقدار[حلقه_فهرست] = جلو_مقدار[حلقه_فهرست] = 수[حلقه_فهرست] = منتظر_ماندن_مقدار[حلقه_فهرست] = 묶임[حلقه_فهرست] = 0; 짝[حلقه_فهرست] = -1; return حلقه_فهرست + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int شماره_درگاه) {
        int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (وضعیت_مقدار[حلقه_فهرست] != 1 || شماره_درگاه < 0 || شماره_درگاه > 65535) return -22;
        if (شماره_درگاه == 0) { do { شماره_درگاه = بعدی_مورد++; if (بعدی_مورد > 65535) بعدی_مورد = 50000; } while (사용중(شماره_درگاه)); }
        if (사용중(شماره_درگاه)) return -98; تبدیل_مقدار[حلقه_فهرست] = شماره_درگاه; 묶임[حلقه_فهرست] = 1; وضعیت_مقدار[حلقه_فهرست] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9; if (وضعیت_مقدار[حلقه_فهرست] != 2 || 연결대기한도 < 1) return -22; وضعیت_مقدار[حلقه_فهرست] = 3; return 0; }
    public static int اتصال(int 열린파일번호, int 통신주소, int شماره_درگاه) {
        int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (شماره_درگاه < 1 || شماره_درگاه > 65535 || وضعیت_مقدار[حلقه_فهرست] > 2) return -22;
        int 수신쪽 = -1; for (int پیوند_درون_خط_مرتب_کردن = 0; پیوند_درون_خط_مرتب_کردن < 16; پیوند_درون_خط_مرتب_کردن++) if (وضعیت_مقدار[پیوند_درون_خط_مرتب_کردن] == 3 && تبدیل_مقدار[پیوند_درون_خط_مرتب_کردن] == شماره_درگاه) 수신쪽 = پیوند_درون_خط_مرتب_کردن;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int پیوند_درون_خط_مرتب_کردن = 0; پیوند_درون_خط_مرتب_کردن < 16; پیوند_درون_خط_مرتب_کردن++) if (منتظر_ماندن_مقدار[پیوند_درون_خط_مرتب_کردن] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (وضعیت_مقدار[حلقه_فهرست] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = ایجاد_ورودی(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        وضعیت_مقدار[حلقه_فهرست] = وضعیت_مقدار[다른번호] = 4; 짝[حلقه_فهرست] = 다른번호; 짝[다른번호] = حلقه_فهرست; تبدیل_مقدار[다른번호] = شماره_درگاه; مشابه_تبدیل[حلقه_فهرست] = شماره_درگاه; مشابه_تبدیل[다른번호] = تبدیل_مقدار[حلقه_فهرست]; منتظر_ماندن_مقدار[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int پذیرش_اتصال(int 열린파일번호) { int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9; if (وضعیت_مقدار[حلقه_فهرست] != 3) return -22; for (int پیوند_درون_خط_مرتب_کردن = 0; پیوند_درون_خط_مرتب_کردن < 16; پیوند_درون_خط_مرتب_کردن++) if (وضعیت_مقدار[پیوند_درون_خط_مرتب_کردن] != 0 && منتظر_ماندن_مقدار[پیوند_درون_خط_مرتب_کردن] == حلقه_فهرست + 1) { منتظر_ماندن_مقدار[پیوند_درون_خط_مرتب_کردن] = 0; return پیوند_درون_خط_مرتب_کردن + 40; } return -11; }
    public static int نوشتن(int 열린파일번호, int 항목수) {
        int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9; if (وضعیت_مقدار[حلقه_فهرست] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int پیوند_درون_خط_مرتب_کردن = 짝[حلقه_فهرست]; if (پیوند_درون_خط_مرتب_کردن < 0) return -32; int 총수 = 1024 - 수[پیوند_درون_خط_مرتب_کردن]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int مقایسه_مرتب_کردن = 0; مقایسه_مرتب_کردن < 총수; مقایسه_مرتب_کردن++) داده_ها[پیوند_درون_خط_مرتب_کردن * 1024 + (جلو_مقدار[پیوند_درون_خط_مرتب_کردن] + 수[پیوند_درون_خط_مرتب_کردن] + مقایسه_مرتب_کردن) % 1024] = 되돌림망.هدایت_مقدار_24592b8a[مقایسه_مرتب_کردن]; 수[پیوند_درون_خط_مرتب_کردن] += 총수; return 총수;
    }
    public static int خواندن(int 열린파일번호, int 항목수) {
        int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9; if (وضعیت_مقدار[حلقه_فهرست] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[حلقه_فهرست] == 0) return 짝[حلقه_فهرست] < 0 ? 0 : -11; if (항목수 > 수[حلقه_فهرست]) 항목수 = 수[حلقه_فهرست];
        for (int مقایسه_مرتب_کردن = 0; مقایسه_مرتب_کردن < 항목수; مقایسه_مرتب_کردن++) 되돌림망.هدایت_مقدار_24592b8a[مقایسه_مرتب_کردن] = داده_ها[حلقه_فهرست * 1024 + (جلو_مقدار[حلقه_فهرست] + مقایسه_مرتب_کردن) % 1024]; جلو_مقدار[حلقه_فهرست] = (جلو_مقدار[حلقه_فهرست] + 항목수) % 1024; 수[حلقه_فهرست] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int حلقه_فهرست = تأیید_صحت(열린파일번호); return حلقه_فهرست < 0 ? -9 : تبدیل_مقدار[حلقه_فهرست]; }
    public static int 상대창구읽기(int 열린파일번호) { int حلقه_فهرست = تأیید_صحت(열린파일번호); return حلقه_فهرست < 0 ? -9 : مشابه_تبدیل[حلقه_فهرست]; }
    public static int بستن(int 열린파일번호) {
        int حلقه_فهرست = تأیید_صحت(열린파일번호); if (حلقه_فهرست < 0) return -9;
        if (وضعیت_مقدار[حلقه_فهرست] == 3) for (int پیوند_درون_خط_مرتب_کردن = 0; پیوند_درون_خط_مرتب_کردن < 16; پیوند_درون_خط_مرتب_کردن++) if (منتظر_ماندن_مقدار[پیوند_درون_خط_مرتب_کردن] == حلقه_فهرست + 1) { if (짝[پیوند_درون_خط_مرتب_کردن] >= 0) 짝[짝[پیوند_درون_خط_مرتب_کردن]] = -1; وضعیت_مقدار[پیوند_درون_خط_مرتب_کردن] = منتظر_ماندن_مقدار[پیوند_درون_خط_مرتب_کردن] = 묶임[پیوند_درون_خط_مرتب_کردن] = 0; }
        if (짝[حلقه_فهرست] >= 0) 짝[짝[حلقه_فهرست]] = -1; وضعیت_مقدار[حلقه_فهرست] = 묶임[حلقه_فهرست] = 수[حلقه_فهرست] = منتظر_ماندن_مقدار[حلقه_فهرست] = 0; return 0;
    }
}
